// =======================
// COLOR DEFINITIONS
// =======================

// Airport Status Colors
var colorOpen = "#90be6d";
var colorClosed = "#f94144";
var colorHelicopter = "#4d908e";
var colorPowerOutage = "#577590";

// Yes/No Colors
var colorYes = "#006e90";
var colorNo = "#f18f01";

// =======================
// AIRPORT STATUS
// =======================
var statusText = Upper($datapoint.airport_status);
if (statusText == "OPEN") {
  statusText = "<div style='text-align:center;'><span style='background-color:" + colorOpen + ";color:#fff;font-weight:bold;padding:4px 10px;border-radius:12px;display:inline-block;'>" + statusText + "</span></div>";
} else if (statusText == "CLOSED") {
  statusText = "<div style='text-align:center;'><span style='background-color:" + colorClosed + ";color:#fff;font-weight:bold;padding:4px 10px;border-radius:12px;display:inline-block;'>" + statusText + "</span></div>";
} else if (statusText == "OPEN FOR HELICOPTERS ONLY") {
  statusText = "<div style='text-align:center;'><span style='background-color:" + colorHelicopter + ";color:#fff;font-weight:bold;padding:4px 10px;border-radius:12px;display:inline-block;'>" + statusText + "</span></div>";
} else if (statusText == "OPEN WITH POWER OUTAGES") {
  statusText = "<div style='text-align:center;'><span style='background-color:" + colorPowerOutage + ";color:#fff;font-weight:bold;padding:4px 10px;border-radius:12px;display:inline-block;'>" + statusText + "</span></div>";
}

// =======================
// RUNWAY OPEN
// =======================
